CREATE DATABASE IF NOT EXISTS taskflowhub DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE taskflowhub;
CREATE TABLE sys_user (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, display_name VARCHAR(80) NOT NULL, role VARCHAR(30) NOT NULL DEFAULT 'client', avatar VARCHAR(8), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE service_item (id BIGINT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(120) NOT NULL, category VARCHAR(80) NOT NULL, description VARCHAR(500) NOT NULL, price DECIMAL(12,2) NOT NULL, cycle VARCHAR(40), icon VARCHAR(16), accent VARCHAR(24), featured TINYINT(1) DEFAULT 0, status VARCHAR(20) DEFAULT 'published', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE order_project (id BIGINT PRIMARY KEY AUTO_INCREMENT, project_name VARCHAR(160) NOT NULL, client_id BIGINT, service_id BIGINT, amount DECIMAL(12,2), status VARCHAR(30) NOT NULL DEFAULT 'pending', deadline DATE, brief TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_order_client FOREIGN KEY(client_id) REFERENCES sys_user(id), CONSTRAINT fk_order_service FOREIGN KEY(service_id) REFERENCES service_item(id));
CREATE TABLE order_activity (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, actor VARCHAR(80) NOT NULL, content VARCHAR(500) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_activity_order FOREIGN KEY(order_id) REFERENCES order_project(id));
